7	/**
8	 * @fileoverview Capture WebMCP CDP events
9	 */
10	
11	import BaseGatherer from '../base-gatherer.js';
12	import {resolveNodeIdToObjectId} from '../driver/dom.js';
13	import {pageFunctions} from '../../lib/page-functions.js';
14	import {ExecutionContext} from '../driver/execution-context.js';
15	
16	/**
17	 * @typedef {Object} WebMCPTool
18	 * @property {string} name
19	 * @property {string} description
20	 * @property {Record<string, any>} inputSchema
21	 * @property {string} frameId
22	 * @property {number} [backendNodeId]
23	 * @property {any} [stackTrace]
24	 * @property {LH.Artifacts.NodeDetails} [nodeDetails]
25	 */
26	class WebMCPTools extends BaseGatherer {
27	  /** @type {LH.Gatherer.GathererMeta} */
28	  meta = {
29	    supportedModes: ['navigation', 'snapshot'],
30	  };
31	
32	  constructor() {
33	    super();
34	    /** @type {WebMCPTool[]} */
35	    this._tools = [];
36	    this._onToolsAdded = this.onToolsAdded.bind(this);
37	    this._onToolsRemoved = this.onToolsRemoved.bind(this);
38	  }
39	
40	  /**
41	   * @param {{tools: WebMCPTool[]}} event
42	   */
43	  // TODO: Handle WebMCP tools per frame.
44	  onToolsAdded(event) {
45	    // Note there is a bug right now in WebMCP.enable CDP where on newly registered tools
46	    // while WebMCP is enabled, the schema is empty. We will have to address that
47	    // eventually.
48	    if (event.tools) {
49	      this._tools.push(...event.tools);
50	    }
51	  }
52	
53	  /**
54	   * @param {{tools: WebMCPTool[]}} event
55	   */
56	  onToolsRemoved(event) {
57	    if (event.tools) {
58	      const removedNames = new Set(event.tools.map(t => t.name));
59	      this._tools = this._tools.filter(t => !removedNames.has(t.name));
60	    }
61	  }
62	
63	  /**
64	   * @param {LH.Gatherer.Context} passContext
65	   */
66	  async startInstrumentation(passContext) {
67	    const session = passContext.driver.defaultSession;
68	
69	    // @ts-expect-error - WebMCP domain might not be in types yet.
70	    session.on('WebMCP.toolsAdded', this._onToolsAdded);
71	    // @ts-expect-error
72	    session.on('WebMCP.toolsRemoved', this._onToolsRemoved);
73	
74	    await session.sendCommand('WebMCP.enable');
75	  }
76	
77	  /**
78	   * @param {LH.Gatherer.Context} passContext
79	   */
80	  async stopInstrumentation(passContext) {
81	    const session = passContext.driver.defaultSession;
82	    // @ts-expect-error
83	    session.off('WebMCP.toolsAdded', this._onToolsAdded);
84	    // @ts-expect-error
85	    session.off('WebMCP.toolsRemoved', this._onToolsRemoved);
86	    try {
87	      await session.sendCommand('WebMCP.disable');
88	    } catch (err) {
89	      // WebMCP.disable might not be implemented or fail, ignore it.
90	    }
91	  }
92	
93	  /**
94	   * @param {LH.Gatherer.Context} context
95	   * @return {Promise<WebMCPTool[]>}
96	   */
97	  async getArtifact(context) {
98	    const session = context.driver.defaultSession;
99	
100	    // Remove duplicates based on name, keeping the latest occurrence.
101	    const toolMap = new Map();
102	    for (const tool of this._tools) {
103	      toolMap.set(tool.name, tool);
104	    }
105	
106	    const resolvedTools = [];
107	    for (const tool of toolMap.values()) {
108	      if (tool.backendNodeId) {
109	        try {
110	          const objectId = await resolveNodeIdToObjectId(session, tool.backendNodeId);
111	          if (objectId) {
112	            const deps = ExecutionContext.serializeDeps([
113	              pageFunctions.getNodeDetails,
114	            ]);
115	            const response = await session.sendCommand('Runtime.callFunctionOn', {
116	              objectId,
117	              functionDeclaration: `function () {
118	                ${deps}
119	                return getNodeDetails(this);
120	              }`,
121	              returnByValue: true,
122	              awaitPromise: true,
123	            });
124	            if (response && response.result && response.result.value) {
125	              tool.nodeDetails = response.result.value;
126	            }
127	          }
128	        } catch (err) {
129	          // Ignore error
130	        }
131	      }
132	      resolvedTools.push(tool);
133	    }
134	
135	    return resolvedTools;
136	  }
137	}
138	
139	export default WebMCPTools;
140

