7	import {Audit} from './audit.js';
8	import * as i18n from '../lib/i18n/i18n.js';
9	
10	const UIStrings = {
11	  /** Title of a Lighthouse audit that lists forms found in the page for WebMCP coverage. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
12	  title: 'WebMCP form coverage',
13	  /** Description of a Lighthouse audit that lists forms found in the page and indicates whether they have WebMCP declarative tool annotations. This is displayed after a user expands the section to see more. No character length limits. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
14	  description: 'Consider adding WebMCP annotations to the forms listed below. This helps AI ' +
15	  'agents identify and interact with these forms more reliably.', // TODO: add a learn more link once available
16	  /** [ICU Syntax] Label for the audit identifying the number of forms missing annotations. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
17	  displayValue: `{itemCount, plural,
18	    =1 {1 form missing annotations}
19	    other {# forms missing annotations}
20	    }`,
21	  /** Label for a column in a data table; entries will be the form element found on the page. */
22	  columnForm: 'Form',
23	};
24	
25	const str_ = i18n.createIcuMessageFn(import.meta.url, UIStrings);
26	
27	class WebMcpFormCoverage extends Audit {
28	  /**
29	   * @return {LH.Audit.Meta}
30	   */
31	  static get meta() {
32	    return {
33	      id: 'webmcp-form-coverage',
34	      scoreDisplayMode: Audit.SCORING_MODES.INFORMATIVE,
35	      title: str_(UIStrings.title),
36	      description: str_(UIStrings.description),
37	      requiredArtifacts: ['Inputs'],
38	      supportedModes: ['navigation', 'snapshot'],
39	    };
40	  }
41	
42	  /**
43	   * @param {LH.Artifacts} artifacts
44	   * @return {LH.Audit.Product}
45	   */
46	  static audit(artifacts) {
47	    const forms = artifacts.Inputs.forms;
48	    const withoutTools = [];
49	
50	    for (const form of forms) {
51	      const hasToolName = !!form.webMcpToolname;
52	      const hasToolDescription = !!form.webMcpTooldescription;
53	
54	      if (!hasToolName && !hasToolDescription) {
55	        withoutTools.push({
56	          node: Audit.makeNodeItem(form.node),
57	        });
58	      }
59	    }
60	
61	    if (withoutTools.length === 0) {
62	      return {
63	        score: 1,
64	      };
65	    }
66	
67	    /** @type {LH.Audit.Details.Table['headings']} */
68	    const headings = [
69	      {key: 'node', valueType: 'node', label: str_(UIStrings.columnForm)},
70	    ];
71	
72	    const details = Audit.makeTableDetails(headings, withoutTools);
73	
74	    return {
75	      score: 1,
76	      displayValue: str_(UIStrings.displayValue, {itemCount: withoutTools.length}),
77	      details,
78	    };
79	  }
80	}
81	
82	export default WebMcpFormCoverage;
83	export {UIStrings};
