7	/**
8	 * @fileoverview Audit that lists registered WebMCP tools.
9	 */
10	
11	import {Audit} from './audit.js';
12	import * as i18n from '../lib/i18n/i18n.js';
13	
14	const UIStrings = {
15	  /** Title of a Lighthouse audit that lists registered WebMCP tools. "WebMCP" stands for "Web Model Context Protocol" and should not be translated. */
16	  title: 'WebMCP tools registered',
17	  /** Description of a Lighthouse audit that lists registered WebMCP tools. This is displayed after a user expands the section to see more. No character length limits. "WebMCP" stands for "Web Model Context Protocol", neither should be translated. */
18	  description: 'Lists the WebMCP tools registered at the time of analysis. ',
19	  /** Label for a column in a data table; entries will be the name of a WebMCP tool. */
20	  columnTool: 'Tool name',
21	  /** Label for a column in a data table; entries will be the description of a WebMCP tool. */
22	  columnDescription: 'Description',
23	  /** Label for a column in a data table; entries will be the source location where an imperative WebMCP tool was registered. */
24	  columnImperativeLocation: 'Source Location',
25	  /** Label for a column in a data table; entries will be the DOM element associated with a declarative WebMCP tool. */
26	  columnDeclarativeElement: 'Element',
27	  /** Label for a column in a data table; entries will be the input schema of a WebMCP tool. */
28	  columnInputSchema: 'Input schema',
29	  /** Title for the table listing imperative WebMCP tools. */
30	  titleImperativeTools: 'Imperative Tools',
31	  /** Title for the table listing declarative WebMCP tools. */
32	  titleDeclarativeTools: 'Declarative Tools',
33	};
34	
35	const str_ = i18n.createIcuMessageFn(import.meta.url, UIStrings);
36	
37	class WebMCPRegisteredTools extends Audit {
38	  /**
39	   * @return {LH.Audit.Meta}
40	   */
41	  static get meta() {
42	    return {
43	      id: 'webmcp-registered-tools',
44	      scoreDisplayMode: Audit.SCORING_MODES.INFORMATIVE,
45	      title: str_(UIStrings.title),
46	      description: str_(UIStrings.description),
47	      requiredArtifacts: ['WebMCPTools'],
48	      supportedModes: ['navigation', 'snapshot'],
49	    };
50	  }
51	
52	  /**
53	   * @param {LH.Artifacts} artifacts
54	   * @return {LH.Audit.Product}
55	   */
56	  static audit(artifacts) {
57	    const tools = artifacts.WebMCPTools || [];
58	
59	    const imperativeResults = [];
60	    const declarativeResults = [];
61	
62	    for (const tool of tools) {
63	      const isDeclarative = typeof tool.backendNodeId === 'number';
64	
65	      let source;
66	      let element;
67	
68	      if (isDeclarative && tool.nodeDetails) {
69	        element = Audit.makeNodeItem(tool.nodeDetails);
70	      } else if (isDeclarative) {
71	        element = `Node ID: ${tool.backendNodeId}`;
72	      } else if (tool.stackTrace) {
73	        const callFrame = tool.stackTrace.callFrames?.[0];
74	        if (callFrame) {
75	          source =
76	            Audit.makeSourceLocation(
77	              callFrame.url, callFrame.lineNumber, callFrame.columnNumber || 0
78	            );
79	        }
80	      }
81	
82	      const item = {
83	        tool: tool.name,
84	        description: tool.description,
85	        inputSchema: JSON.stringify(tool.inputSchema, null, 2),
86	      };
87	
88	      if (isDeclarative) {
89	        declarativeResults.push({
90	          ...item,
91	          element,
92	        });
93	      } else {
94	        imperativeResults.push({
95	          ...item,
96	          source,
97	        });
98	      }
99	    }
100	
101	    const list = [];
102	
103	    if (imperativeResults.length > 0) {
104	      /** @type {LH.Audit.Details.Table['headings']} */
105	      const headings = [
106	        {key: 'tool', valueType: 'text', label: str_(UIStrings.columnTool)},
107	        {key: 'description', valueType: 'text', label: str_(UIStrings.columnDescription)},
108	        {key: 'source', valueType: 'source-location',
109	          label: str_(UIStrings.columnImperativeLocation)},
110	        {key: 'inputSchema', valueType: 'code', label: str_(UIStrings.columnInputSchema)},
111	      ];
112	      const table = Audit.makeTableDetails(headings, imperativeResults);
113	      list.push(Audit.makeListDetailSectionItem(table, str_(UIStrings.titleImperativeTools)));
114	    }
115	
116	    if (declarativeResults.length > 0) {
117	      /** @type {LH.Audit.Details.Table['headings']} */
118	      const headings = [
119	        {key: 'tool', valueType: 'text', label: str_(UIStrings.columnTool)},
120	        {key: 'description', valueType: 'text', label: str_(UIStrings.columnDescription)},
121	        {key: 'element', valueType: 'node', label: str_(UIStrings.columnDeclarativeElement)},
122	        {key: 'inputSchema', valueType: 'code', label: str_(UIStrings.columnInputSchema)},
123	      ];
124	      const table = Audit.makeTableDetails(headings, declarativeResults);
125	      list.push(Audit.makeListDetailSectionItem(table, str_(UIStrings.titleDeclarativeTools)));
126	    }
127	
128	    if (list.length === 0) {
129	      return {
130	        score: 1,
131	      };
132	    }
133	
134	    return {
135	      score: 1,
136	      details: Audit.makeListDetails(list),
137	    };
138	  }
139	}
140	
141	export default WebMCPRegisteredTools;
142	export {UIStrings};
